import collections
MARKS=['⊢','⊣','≻','≺','⋈','⊤','∈','∋','⊙','⊥','⊞','◻']
def b12(n,w):
    d=[]
    for _ in range(w): n,r=divmod(n,12); d.append(MARKS[r])
    return "".join(reversed(d))
def addr(word):
    n=0
    for ch in word: n=n*27+(ord(ch)-96)
    return b12(n,12)
wl=[l.strip() for l in open('bip39wordlist.txt') if l.strip()][:2048]
